(()=>{
 const symbols={'↗':'arrow-up-right-01','←':'arrow-left-01','→':'arrow-right-01','↑':'arrow-up-01','↓':'arrow-down-01','×':'cancel-01','☾':'moon-02','◐':'moon-02','☀':'sun-01'};
 function icon(name){const holder=document.createElement('template');holder.innerHTML=portfolioIcons[name];return holder.content.firstElementChild.cloneNode(true)}
 function apply(){
  document.querySelectorAll('.nav-home svg,.nav-toggle svg,.theme-toggle svg').forEach(svg=>{if(svg.dataset.hugeicon)return;let name=svg.closest('.nav-home')?'home-01':svg.closest('.theme-toggle')?(document.body.dataset.theme==='dark'?'sun-01':'moon-02'):'menu-01';svg.replaceWith(icon(name))});
  const walker=document.createTreeWalker(document.body,NodeFilter.SHOW_TEXT,{acceptNode(node){return node.parentElement?.closest('a,button')&&!node.parentElement.closest('svg,script,style')&&/[↗←→↑↓×☾◐☀]/.test(node.nodeValue)?NodeFilter.FILTER_ACCEPT:NodeFilter.FILTER_REJECT}});const nodes=[];while(walker.nextNode())nodes.push(walker.currentNode);
  nodes.forEach(node=>{const fragment=document.createDocumentFragment();for(const part of node.nodeValue.split(/([↗←→↑↓×☾◐☀])/)){fragment.append(symbols[part]?icon(symbols[part]):document.createTextNode(part))}node.replaceWith(fragment)});
 }
 let scheduled=false;const observer=new MutationObserver(records=>{if(!records.some(r=>r.target.parentElement?.closest('a,button')||r.target.closest?.('a,button')||[...r.addedNodes].some(n=>n.nodeType===1&&(n.matches?.('a,button')||n.querySelector?.('a,button')))))return;if(scheduled)return;scheduled=true;requestAnimationFrame(()=>{observer.disconnect();apply();scheduled=false;observer.observe(document.body,{childList:true,subtree:true,characterData:true})})});apply();observer.observe(document.body,{childList:true,subtree:true,characterData:true});
})();
